Object.assign(window.TEM8_DICTIONARY, {"wrongly":{"oxford":{"phon":"ˈrɒŋli","pos":"adverb","senses":[{"en":"in a way that is not right or correct","cn":"错误地","ex":{"en":"He assumed, wrongly, that she did not care.","cn":"他误以为她并不在乎。"}},{"en":"in a way that is not fair or not morally right","cn":"不公正地；不道德地","ex":{"en":"She was wrongly accused of stealing.","cn":"她被诬告犯了偷盗罪。"}}]},"media":{"uk":"media/uk/wrongly__gb_1.mp3","us":"media/us/wrongly__us_1.mp3"},"examples":[{"en":"Rightly or wrongly, they felt they should have been better informed (= I do not know whether they were right to feel this way).","cn":"不论对错，他们觉得应该让他们了解到更多的情况。"},{"en":"They knew they had acted wrongly.","cn":"他们知道他们做得不对。"}]},"wrapping":{"oxford":{"phon":"ˈræpɪŋ","pos":"noun","senses":[{"en":"paper, plastic, etc. used for covering something in order to protect it","cn":"包装材料；包装纸；包装塑料","ex":{"en":"She tore the cellophane wrapping off the box.","cn":"她把包装盒子的玻璃纸撕了下来。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"包装纸;包装塑料；包装材料","en":"Wrapping is something such as paper or plastic which is used to cover and protect something.","ex":{"en":"...food wrapping","cn":"食品包装纸"}}]},"media":{"uk":"media/uk/wrapping__gb_1.mp3","us":"media/us/wrapping__us_1.mp3"},"examples":[{"en":"She tore the cellophane wrapping off the box.","cn":"她把包装盒子的玻璃纸撕了下来。"},{"en":"The painting was still in its wrappings.","cn":"那幅画仍然包装着。"}]},"wrapped":{"media":{"uk":"media/uk/wrapped__gb_1.mp3","us":"media/us/wrapped__us_1.mp3"},"oxford":{"phon":"ræpt","pos":"adjective","senses":[{"en":"extremely pleased","cn":"极高兴的；十分满意的","ex":{"en":"The minister declared that he was wrapped.","cn":"部长公开表示他特别满意。"}}]},"examples":[{"en":"The minister declared that he was wrapped.","cn":"部长公开表示他特别满意。"}]},"written":{"media":{"uk":"media/uk/written__gb_2.mp3","us":"media/us/written__us_2.mp3"},"oxford":{"phon":"ˈrɪtn","pos":"adjective","senses":[{"en":"expressed in writing rather than in speech","cn":"书面的","g":"[usually before noun]","ex":{"en":"Having a written record of what I've done is very valuable.","cn":"书面记录我所做的事情非常有益。"}},{"en":"involving writing rather than speaking or practical skills","cn":"书面的；笔头的","g":"[usually before noun]","ex":{"en":"a written test","cn":"笔试"}},{"en":"in the form of a letter, document, etc. and therefore official","cn":"以书信（或文件等）形式的；书面的；成文的；正式的","g":"[only before noun]","ex":{"en":"No portion of this site may be copied without express written consent.","cn":"未经明确书面同意，本网站的任何部分概不得复制。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Written is the past participle of write ."},{"pos":"ADJ 形容词","cn":"(测验、作业等)书面的，笔头的","en":"A written test or piece of work is one which involves writing rather than doing something practical or giving spoken answers.","ex":{"en":"Learners may have to take a written exam before they pass their driving test","cn":"学员在通过驾照考试前可能得参加笔试。"}},{"pos":"ADJ 形容词","cn":"(协议、规定、法律等)成文的，书面的","en":"A written agreement, rule, or law has been officially written down.","ex":{"en":"The newspaper broke a written agreement not to sell certain photographs","cn":"这家报纸违反了不出售某些摄影作品的书面协议。"}},{"pos":"","cn":"","en":"to be written all over someone's face→see: ;"}]},"examples":[{"en":"the permanence of the written word","cn":"书面语传之久远的特性"},{"en":"written communication skills","cn":"书面交流技巧"}]},"write":{"media":{"uk":"media/uk/write__gb_1.mp3","us":"media/us/write__us_1.mp3"},"oxford":{"phon":"raɪt","pos":"verb","senses":[{"en":"to make letters or numbers on a surface, especially using a pen or a pencil","cn":"书写；写字","g":"[intransitive, transitive]","sc":"letters/numbers","ex":{"en":"In some countries children don't start learning to read and write until they are six.","cn":"有些国家的儿童到了六岁才开始学习读书写字。"}},{"en":"to produce something in written form so that people can read, perform or use it, etc.","cn":"写作；作曲；编写","g":"[transitive, intransitive]","sc":"book/music/program","ex":{"en":"to write a novel/song/computer program","cn":"写小说；写歌；编写计算机程序"}},{"en":"to put information, a message of good wishes, etc. in a letter or an email and send it to somebody","cn":"写信；写电邮","g":"[intransitive, transitive]","lab":"North American English","sc":"a letter/an email","ex":{"en":"Bye! Don't forget to write.","cn":"再见！别忘了写信。"}},{"en":"to state the information or the words mentioned","cn":"写道；（以文字）说","g":"[transitive, intransitive]","sc":"state in writing","ex":{"en":"The author writes that this theory has now been disproved.","cn":"作者写道，这一理论现已被证明不成立。"}},{"en":"to put information in the appropriate places on a form","cn":"填写（表格等）","g":"[transitive]","sc":"form","ex":{"en":"to write (out) a cheque","cn":"开一张支票"}},{"en":"to record data in the memory of a computer","cn":"将（数据）写入（存储器）","g":"[transitive, intransitive]","sc":"computing","ex":{"en":"An error was reported when he tried to write data to the file for the first time.","cn":"当他第一次尝试把数据写入文档时，报告说有错。"}},{"en":"to work correctly or in the way mentioned","cn":"好使；能使用；以…方式写","g":"[intransitive]","sc":"of pen/pencil","ex":{"en":"This pen won't write.","cn":"这支钢笔不好使。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"写;书写;写字","en":"When you write something on a surface, you use something such as a pen or pencil to produce words, letters, or numbers on the surface.","ex":{"en":"If you'd like one, simply write your name and address on a postcard and send it to us","cn":"如果你想要一个的话，只要把姓名、住址写在一张明信片上寄给我们就行。"}},{"pos":"VERB 动词","cn":"写(书、诗等);创作(歌曲)","en":"If you write something such as a book, a poem, or a piece of music, you create it and record it on paper or perhaps on a computer.","ex":{"en":"I had written quite a lot of orchestral music in my student days","cn":"我在学生时代创作过很多管弦乐作品。"}},{"pos":"VERB 动词","cn":"写作，著述（通常以出版为目的）","en":"Someone who writes creates books, stories, or articles, usually for publication.","ex":{"en":"Jay wanted to write","cn":"杰伊想要写作。"}},{"pos":"VERB 动词","cn":"写(信);给…写信(美国英语亦可用 write someone)","en":"When you write to someone or write them a letter, you give them information, ask them something, or express your feelings in a letter. In American English, you can also write someone. nothing to write home about→see: ;","ex":{"en":"Many people have written to me on this subject","cn":"很多人给我写信探讨这个问题。"}},{"pos":"VERB 动词","cn":"(在信、书或文章中)写道，说道","en":"If someone writes that something is the case, they say it in a letter, book, or article.","ex":{"en":"'Some six months later,' Freud writes, 'Hans had got over his jealousy.'","cn":"“大约6个月后，”弗洛伊德写道，“汉斯克服了他的嫉妒心理。”"}},{"pos":"VERB 动词","cn":"开具(支票、收据、处方等)","en":"When someone writes something such as a cheque, receipt, or prescription, they put the necessary information on it and usually sign it.","ex":{"en":"Snape wrote a receipt with a gold fountain pen","cn":"斯内普用金笔开了一张收据。"}},{"pos":"VERB 动词","cn":"(往计算机或磁盘)录入，写入","en":"If you write to a computer or a disk, you record data on it.","ex":{"en":"You should write-protect all disks that you do not usually need to write to.","cn":"你应该对你通常不需要写入内容的磁盘进行写保护。"}},{"pos":"","cn":"","en":"相关词组：write back write down write in write into write off write out write up"}]},"examples":[{"en":"In his latest book he writes that the theory has since been disproved.","cn":"他在最近的一部书里写道，那个理论后来已被证明不能成立。"},{"en":"‘Of all my books,’ wrote Dickens, ‘I like this the best.’","cn":"狄更斯写道：“在我所有的书中，我最喜欢这本”。"}]},"writings":{"oxford":{"phon":"ˈraɪtɪŋ","pos":"noun","senses":[{"en":"the activity of writing, in contrast to reading, speaking, etc.","cn":"写；书写；写作"},{"en":"the activity of writing books, articles, etc., especially as a job （","cn":"专职）写作；著书立说"}]},"media":{"uk":"media/uk/writing__gb_1.mp3","us":"media/us/writing__us_1.mp3"}},"wrap":{"media":{"uk":"media/uk/wrap__gb_1.mp3","us":"media/us/wrap__us_1.mp3"},"oxford":{"phon":"ræp","pos":"verb","senses":[{"en":"to cover something completely in paper or other material, for example when you are giving it as a present","cn":"包，裹（礼物等）","g":"[transitive]","ex":{"en":"He spent the evening wrapping up the Christmas presents.","cn":"他花了一个晚上的时间把圣诞礼物都包了起来。"}},{"en":"to cover something/somebody in material, for example in order to protect it/them","cn":"用…包裹（或包扎、覆盖等）","g":"[transitive]","ex":{"en":"Wrap the meat in foil before you cook it.","cn":"把肉用锡箔裹起来后再烹调。"}},{"en":"to put something around something/somebody","cn":"用…缠绕","g":"[transitive]","ex":{"en":"A scarf was wrapped around his neck.","cn":"他的脖子上围着一条围巾。"}},{"en":"to cause a word or text to be carried over to a new line as the end of the previous line is reached by the writer; to be carried over in this way","cn":"（使文字）换行","g":"[transitive, intransitive]","lab":"computing","ex":{"en":"How can I wrap the text around?","cn":"我怎么才能使文本换行呢？"}},{"en":"a piece of cloth that a woman wears around her shoulders for decoration or to keep warm, or a loose piece of clothing worn over something else","cn":"（女用）披肩，围巾，裹巾","g":"[countable]","ex":{"en":"a cashmere wrap","cn":"羊绒裹身布"},"pos":"noun"},{"en":"paper, plastic, etc. that is used for wrapping things in","cn":"包裹（或包装）材料","g":"[uncountable]","ex":{"en":"We stock a wide range of cards and gift wrap.","cn":"我们备有各种各样的贺卡和礼品包装材料。"},"pos":"noun"},{"en":"used when making a film to say that filming has finished","cn":"（拍摄电影时）完成拍摄，停机","g":"[singular]","ex":{"en":"Cut! That's a wrap.","cn":"停！就拍摄到这儿。"},"pos":"noun"},{"en":"a type of sandwich made with a cold tortilla rolled around meat or vegetables","cn":"墨西哥卷（用冻玉米薄饼裹肉或蔬菜的三明治）","g":"[countable]","pos":"noun"},{"en":"a special cover for any small electronic device that you can carry with you","cn":"（便携式电子设备的）护套，保护壳","g":"[countable]","ex":{"en":"These are vinyl wraps that cover your entire phone with one thin sheath.","cn":"这些是乙烯基包装，用一层薄薄的护套覆盖您的整个手机。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(用纸、布等)包，裹","en":"When you wrap something, you fold paper or cloth tightly round it to cover it completely, for example in order to protect it or so that you can give it to someone as a present.","ex":{"en":"Harry had carefully bought and wrapped presents for Mark to give them","cn":"哈里精心购置了礼物又仔细包好，让马克交给他们。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"包装材料;包裹物","en":"Wrap is the material that something is wrapped in.","ex":{"en":"I tucked some plastic wrap around the sandwiches to keep them from getting stale.","cn":"我用塑料包装纸把三明治裹起来，防止变质。"}},{"pos":"VERB 动词","cn":"用…包;用…裹","en":"When you wrap something such as a piece of paper or cloth round another thing, you put it around it.","ex":{"en":"She wrapped a handkerchief around her bleeding palm","cn":"她用手绢将流血的手掌包扎起来。"}},{"pos":"VERB 动词","cn":"用(手臂、指头或腿)围紧;用…绕住","en":"If someone wraps their arms, fingers, or legs around something, they put them firmly around it.","ex":{"en":"He wrapped his arms around her.","cn":"他紧紧搂住她。"}},{"pos":"N-COUNT 可数名词","cn":"披肩;围巾","en":"A wrap is a piece of clothing which women wear round their shoulders, either to keep them warm when wearing an evening dress, or for decoration over a coat."},{"pos":"PHRASE 短语","cn":"保密，秘而不宣（常指待日后宣布）","en":"If you keep something under wraps, you keep it secret, often until you are ready to announce it at some time in the future.","ex":{"en":"The bids were submitted in May and were meant to have been kept under wraps until October","cn":"标书5月份递交，本欲10月份才予以公布。"}},{"pos":"","cn":"","en":"相关词组：wrap up"}]},"examples":[{"en":"The text wraps around if it is too long to fit the screen.","cn":"如果文本太长，在显示屏放不下的话，会自动换行。"},{"en":"He spent the evening wrapping up the Christmas presents.","cn":"他花了一个晚上的时间把圣诞礼物都包了起来。"}]},"wretched":{"media":{"uk":"media/uk/wretched__gb_1.mp3","us":"media/us/wretched__us_1.mp3"},"oxford":{"phon":"ˈretʃɪd","pos":"adjective","senses":[{"en":"feeling ill or unhappy","cn":"感到不适的；难受的；不愉快的","g":"[not usually before noun]","ex":{"en":"You look wretched—what's wrong?","cn":"你看起来愁眉苦脸的，怎么啦？"}},{"en":"extremely bad or unpleasant","cn":"极坏的；恶劣的","lab":"formal","ex":{"en":"She had a wretched time of it at school.","cn":"她上学时的日子十分难熬。"}},{"en":"making you feel sympathy or making you sad","cn":"可怜的；悲惨的","g":"[usually before noun]","lab":"formal","ex":{"en":"She finally agreed to have the wretched animal put down.","cn":"她最后同意用药结束这个可怜的动物的生命。"}},{"en":"used to show that you think that somebody/something is extremely annoying","cn":"（表示憎恶）该死的，无法容忍的","g":"[only before noun]","lab":"informal","ex":{"en":"Is it that wretched woman again?","cn":"这又是那个该死的女人吗？"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不幸的;可怜的;苦难的","en":"You describe someone as wretched when you feel sorry for them because they are in an unpleasant situation or have suffered unpleasant experiences.","ex":{"en":"You have built up a huge property empire by buying from wretched people who had to sell or starve.","cn":"你靠从那些不卖房就得挨饿的可怜人手里买下房子后建立起了庞大的房产帝国。"}},{"pos":"ADJ 形容词","cn":"讨厌的;混账的;该死的","en":"You use wretched to describe someone or something that you dislike or feel angry with.","ex":{"en":"Wretched woman, he thought, why the hell can't she wait?","cn":"他想，可恶的女人，她怎么就不能等一等呢？"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"苦恼的;难过的;哀伤的","en":"Someone who feels wretched feels very unhappy.","ex":{"en":"I feel really confused and wretched","cn":"我觉得十分迷惘，难过极了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恶劣的;低劣的","en":"If you describe something as wretched, you are emphasizing that it is very bad or of very poor quality.","ex":{"en":"What a wretched excuse","cn":"多么拙劣的借口！"}}]},"examples":[{"en":"She finally agreed to have the wretched animal put down.","cn":"她最后同意把这头可怜的动物人道毁灭。"},{"en":"I felt wretched about the way things had turned out.","cn":"事情落了这么个结局，我感到很难受。"}]},"wreck":{"media":{"uk":"media/uk/wreck__gb_1.mp3","us":"media/us/wreck__us_1.mp3"},"oxford":{"phon":"rek","pos":"noun","senses":[{"en":"a ship that has sunk or that has been very badly damaged","cn":"沉船；严重损毁的船","ex":{"en":"They're going to try and raise the wreck from the seabed.","cn":"他们将设法从海底捞起失事船只残骸。"}},{"en":"a car, plane, etc. that has been very badly damaged in an accident","cn":"（事故中）遭严重毁坏的汽车（或飞机等）","lab":"figurative","ex":{"en":"Two passengers are still trapped in the wreck.","cn":"有两名乘客仍被困在失事的车辆里。"}},{"en":"a person who is in a bad physical or mental condition","cn":"（身体或精神上）受到严重损伤的人","g":"[usually singular]","lab":"informal","ex":{"en":"Physically, I was a total wreck.","cn":"从身体上说，我完全是一个废人。"}},{"en":"a vehicle, building, etc. that is in very bad condition","cn":"状况非常糟糕的车辆（或建筑物等）","lab":"informal","ex":{"en":"The house was a wreck when we bought it.","cn":"我们买下这座房子时，它破烂不堪。"}},{"en":"an accident in which a vehicle hits something, for example another vehicle, usually causing damage and often injuring or killing the passengers","cn":"撞车；碰撞；相撞","lab":"North American English","ex":{"en":"a car/train wreck","cn":"汽车／火车失事"}},{"en":"to damage or destroy something","cn":"破坏；损坏；毁坏","ex":{"en":"A bomb completely wrecked the building.","cn":"一颗炸弹把这座建筑完全炸毁了。"},"pos":"verb"},{"en":"to cause something to fail completely","cn":"毁灭；毁掉","ex":{"en":"The weather wrecked all our plans.","cn":"天气把我们的计划全都毁了。"},"pos":"verb"},{"en":"to damage a ship so much that it sinks or can no longer sail","cn":"使（船舶）失事；使遇难；使下沉","g":"[usually passive]","ex":{"en":"The ship was wrecked off the coast of France.","cn":"那艘船在法国的沿岸失事。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"毁掉;毁坏;损坏","en":"To wreck something means to completely destroy or ruin it.","ex":{"en":"He wrecked the garden","cn":"他毁掉了花园。"}},{"pos":"VERB 动词","cn":"使(船舶)失事；使遇难","en":"If a ship is wrecked, it is damaged so much that it sinks or can no longer sail.","ex":{"en":"The ship was wrecked by an explosion.","cn":"这艘船被炸毁了。"}},{"pos":"N-COUNT 可数名词","cn":"失事的船只(或汽车、飞机);损毁的建筑","en":"A wreck is something such as a ship, car, plane, or building which has been destroyed, usually in an accident.","ex":{"en":"...the wreck of a sailing ship","cn":"帆船的残骸"}},{"pos":"N-COUNT 可数名词","cn":"车祸；交通事故","en":"A wreck is an accident in which a moving vehicle hits something and is damaged or destroyed.","ex":{"en":"He was killed in a car wreck.","cn":"他在一场车祸中丧生。"}},{"pos":"N-COUNT 可数名词","cn":"精疲力竭的人;身体状况极差的人","en":"If you say that someone is a wreck, you mean that they are very exhausted or unhealthy.","ex":{"en":"You look a wreck","cn":"你看起来身体很糟糕。"}}]},"examples":[{"en":"( figurative ) They still hoped to salvage something from the wreck of their marriage.","cn":"他们仍然希望从他们破碎的婚姻中挽回点什么。"},{"en":"Two passengers are still trapped in the wreck.","cn":"有两名乘客仍被困在失事的车辆里。"}]},"wraps":{"oxford":{"phon":"ræp","pos":"verb","senses":[{"en":"to cover sth completely in paper or other material, for example when you are giving it as a present","cn":"包，裹（礼物等）"},{"en":"to cover sth/sb in material, for example in order to protect it/them","cn":"用 … 包裹（或包扎、覆盖等）"}]},"media":{"uk":"media/uk/wrap__gb_1.mp3","us":"media/us/wrap__us_1.mp3"}},"wrong":{"media":{"uk":"media/uk/wrong__gb_1.mp3","us":"media/us/wrong__us_1.mp3"},"oxford":{"phon":"rɒŋ","pos":"adjective","senses":[{"en":"not right or correct","cn":"错误的；不对的；不正确的","sc":"not correct","ex":{"en":"I got all the answers wrong.","cn":"我的答案全都错了。"}},{"en":"not right about something/somebody","cn":"出错；搞错；有错误","g":"[not before noun]","lab":"informal","sc":"not correct","ex":{"en":"I think she lives at number 44, but I could be wrong.","cn":"我想她是住在 44 号，不过我可能记错了。"}},{"en":"causing problems or difficulties; not as it should be","cn":"引起问题（或麻烦）；有毛病；不正常","g":"[not before noun]","sc":"causing problems","ex":{"en":"Is anything wrong? You look worried.","cn":"出了什么事？看你愁眉苦脸的样子。"}},{"en":"not suitable, right or what you need","cn":"不合适的；不适当的；不合意的","g":"[usually before noun]","sc":"not suitable","ex":{"en":"He's the wrong person for the job.","cn":"他不适合做这项工作。"}},{"en":"not morally right or honest","cn":"不道德；不义；不诚实","g":"[not usually before noun]","sc":"not morally right","ex":{"en":"This man has done nothing wrong.","cn":"这位男子没有做过不正当的事。"}},{"en":"in a way that produces a result that is not correct or that you do not want","cn":"错误地；不正确；不对","ex":{"en":"My name is spelt wrong.","cn":"我的名字给拼错了。"},"pos":"adverb"},{"en":"behaviour that is not honest or morally acceptable","cn":"不义行为；欺骗行径；恶行","g":"[uncountable]","ex":{"en":"Children must be taught the difference between right and wrong.","cn":"必须教儿童分清是非。"},"pos":"noun"},{"en":"an act that is not legal, honest or morally acceptable","cn":"犯罪；欺骗；罪恶","g":"[countable]","lab":"formal","ex":{"en":"It is time to forgive past wrongs if progress is to be made.","cn":"如果想有进步，现在就该宽恕过去的罪过。"},"pos":"noun"},{"en":"to treat somebody badly or in an unfair way","cn":"不公正（或不诚实）对待","ex":{"en":"He felt deeply wronged by the allegations.","cn":"这些指控让他感到深受冤枉。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有麻烦的;有问题的","en":"If you say there is something wrong, you mean there is something unsatisfactory about the situation, person, or thing you are talking about.","ex":{"en":"Pain is the body's way of telling us that something is wrong","cn":"疼痛是身体在告诉我们有地方出问题了。"}},{"pos":"ADJ 形容词","cn":"(选择)错误的，不适宜的","en":"If you choose the wrong thing, person, or method, you make a mistake and do not choose the one that you really want.","ex":{"en":"He went to the wrong house","cn":"他去错了房子。"}},{"pos":"ADJ 形容词","cn":"(决定、选择、行动等)错误的，不适当的","en":"If something such as a decision, choice, or action is the wrong one, it is not the best or most suitable one.","ex":{"en":"I really made the wrong decision there","cn":"在那点上我的决定确实错了。"}},{"pos":"ADJ 形容词","cn":"不正确的;与事实不符的","en":"If something is wrong, it is incorrect and not in accordance with the facts.","ex":{"en":"How do you know that this explanation is wrong?","cn":"你怎么知道这个解释是错误的呢？"}},{"pos":"ADJ 形容词","cn":"（机器设备）出毛病的，出故障的","en":"If something is wrong or goes wrong with a machine or piece of equipment, it stops working properly.","ex":{"en":"We think there's something wrong with the computer","cn":"我们认为计算机出了故障。"}},{"pos":"ADJ 形容词","cn":"(言论或想法)错的，错误的","en":"If you are wrong about something, what you say or think about it is not correct.","ex":{"en":"I was wrong about it being a casual meeting","cn":"我误以为这是个非正式会议。"}},{"pos":"ADV 副词","cn":"(通常用于生气时)你想错了／你听错了","en":"You can use wrong in expressions such as you thought wrong and you heard wrong to tell someone that what they thought or were told is incorrect, usually when you are annoyed.","ex":{"en":"'I thought you and I were going to spend the night together,' he whispered. 'You thought wrong,' Nancy whispered back.","cn":"“我以为我和你要一起过夜呢。”他小声说。“你想错了。”南茜小声回应道。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（做某事是）不对的，不道德的","en":"If you think that someone was wrong to do something, you think that they should not have done it because it was bad or immoral.","ex":{"en":"She was wrong to leave her child alone","cn":"她不该把孩子单独留在那儿。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(活动或行动)不道德的，不可取的","en":"Wrong is used to refer to activities or actions that are considered to be morally bad and unacceptable.","ex":{"en":"Is it wrong to try to save the life of someone you love?","cn":"尽力挽救所爱之人的生命难道错了吗？"}},{"pos":"N-COUNT 可数名词","cn":"不公平行为;不道德行为","en":"A wrong is an unfair or immoral action.","ex":{"en":"I intend to right that wrong","cn":"我打算纠正那个错误。"}},{"pos":"VERB 动词","cn":"不公正地对待;冤枉","en":"If someone wrongs you, they treat you in an unfair way.","ex":{"en":"You have wronged my mother","cn":"你冤枉了我妈妈。"}},{"pos":"ADJ 形容词","cn":"不能被社会所接受的;不可取的","en":"You use wrong to describe something which is not thought to be socially acceptable or desirable.","ex":{"en":"If you went to the wrong school, you won't get the job","cn":"如果你进错了学校，就得不到这份工作。"}},{"pos":"PHRASE 短语","cn":"别误会我的意思","en":"You say 'Don't get me wrong' when you want to make sure that someone does not get an incorrect idea about what you are doing or saying, or about why you are doing or saying it.","ex":{"en":"Don't get me wrong, it's interesting work. But it's not permanent","cn":"别误会我的意思，这个工作很有意思，可惜不是长期性的。"}},{"pos":"PHRASE 短语","cn":"(情况)出岔子，出差错","en":"If a situation goes wrong, it stops progressing in the way that you expected or intended, and becomes much worse.","ex":{"en":"It all went horribly wrong","cn":"情况完全变得一团糟。"}},{"pos":"PHRASE 短语","cn":"(道义或法律上)错的，不对的","en":"If someone who is involved in an argument or dispute has behaved in a way which is morally or legally wrong, you can say that they are in the wrong .","ex":{"en":"He didn't press charges because he was in the wrong","cn":"他没有起诉，因为过错在他。"}},{"pos":"CONVENTION 惯用语","cn":"冤冤相报何时了","en":"If someone says 'Two wrongs don't make a right', they mean that you should not do harm to a person who has done harm to you, even if you think that person deserves it."},{"pos":"","cn":"","en":"not far wrong→see: ; to get off on the wrong foot→see: ; to get hold of the wrong end of the stick→see: ; to be barking up the wrong tree→see: ;"}]},"examples":[{"en":"‘I thought you were going out.’ ‘Well you must have thought wrong , then!’ “","cn":"我原以为你要出去呢。” “啊，那你一定是想错了！”"},{"en":"( informal ) Correct me if I'm wrong (= I may be wrong) but didn't you say you two knew each other?","cn":"我若说错了请你纠正，你不是说过你们彼此认识吗？"}]},"writing":{"media":{"uk":"media/uk/writing__gb_1.mp3","us":"media/us/writing__us_1.mp3"},"oxford":{"phon":"ˈraɪtɪŋ","pos":"noun","senses":[{"en":"the activity of writing, in contrast to reading, speaking, etc.","cn":"写；书写；写作","g":"[uncountable]","ex":{"en":"Our son’s having problems with his reading and writing (= at school).","cn":"我们儿子在读写方面有困难。"}},{"en":"the activity of writing books, articles, etc., especially as a job","cn":"（专职）写作；著书立说","g":"[uncountable]","ex":{"en":"Only later did she discover a talent for writing.","cn":"她后来才发现自己的写作天分。"}},{"en":"books, articles, etc. in general","cn":"著作；文字作品；文章","g":"[uncountable]","ex":{"en":"The review is a brilliant piece of writing.","cn":"这篇评论很精彩。"}},{"en":"words that have been written or painted on something","cn":"（书写或涂画的）文字","g":"[uncountable]","ex":{"en":"There was writing all over the desk.","cn":"书桌上写满了字。"}},{"en":"the particular way in which somebody forms letters when they write","cn":"笔迹；字迹；书法","g":"[uncountable]","ex":{"en":"Who's this from? I don't recognize the writing.","cn":"这是谁写来的？我辨认不出笔迹。"}},{"en":"a group of pieces of writing, especially by a particular person or on a particular subject","cn":"（某作家或专题的）著作，作品","g":"[plural]","ex":{"en":"His experiences in India influenced his later writings.","cn":"他在印度的经历影响了他后来的著作。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(写下或印出的)文字","en":"Writing is something that has been written or printed.","ex":{"en":"'It's from a notebook,' the sheriff said, 'And there's writing on it.'","cn":"“这是在一个笔记本里找到的，”法官道，“上面还有文字。”"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指评论语言风格时的)文字作品，文章","en":"You can refer to any piece of written work as writing, especially when you are considering the style of language used in it.","ex":{"en":"The writing is brutally tough and savagely humorous","cn":"该作品带有残酷的强悍和野性的幽默感。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指为赚取稿费而进行的)写作","en":"Writing is the activity of writing, especially of writing books for money.","ex":{"en":"She had begun to be a little bored with novel writing.","cn":"她开始对写小说有些厌倦了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"笔迹;字迹;书写","en":"Your writing is the way that you write with a pen or pencil, which can usually be recognized as belonging to you.","ex":{"en":"It was a little difficult to read your writing","cn":"你写的字有点不好认。"}},{"pos":"N-PLURAL 复数名词","cn":"(尤指某一作者有关某一专题的全部)著作，作品","en":"An author's writings are all the things that he or she has written, especially on a particular subject.","ex":{"en":"Althusser's writings are focused mainly on France","cn":"阿尔都塞的著作主要是论述法国的。"}},{"pos":"PHRASE 短语","cn":"凶兆毕现；有大难临头的预兆","en":"If you say that the writing is on the wall, you mean that there are clear signs that a situation is going to become very difficult or unpleasant.","ex":{"en":"The writing is clearly on the wall. If we do nothing about it, we shall only have ourselves to blame.","cn":"凶兆显而易见。如果我们对此毫无行动，就只能怨自己了。"}}]},"examples":[{"en":"It is amazing that not one of them saw the writing on the wall.","cn":"令人吃惊的是他们就没有一个人看出大难临头的预兆。"},{"en":"Only later did she discover a talent for writing.","cn":"她到了较后期才发现自己的写作天分。"}]},"wrench":{"media":{"img":["media/ldoce/img/wrench.jpg","media/pic/tools_diy_comp.jpg"],"uk":"media/uk/wrench__gb_1.mp3","us":"media/us/wrench__us_1.mp3"},"oxford":{"phon":"rentʃ","pos":"verb","senses":[{"en":"to pull or twist something/somebody/yourself suddenly and violently","cn":"猛拉；猛扭；猛拧","g":"[transitive, intransitive]","lab":"figurative","ex":{"en":"The bag was wrenched from her grasp.","cn":"那个包从她紧握的手里被夺了出来。"}},{"en":"to twist and injure a part of your body, especially your ankle or shoulder","cn":"扭伤（脚踝、肩膀等）","g":"[transitive]","ex":{"en":"She wrenched her knee when she fell.","cn":"她跌倒时把膝盖扭伤了。"}},{"en":"to make somebody feel great pain or unhappiness, especially so that they make a sound or cry","cn":"使痛苦，使十分难过（尤指以致哭喊出声）","g":"[transitive, intransitive]","lab":"formal","ex":{"en":"His words wrenched a sob from her.","cn":"他的话使得她难过得抽泣起来。"}},{"en":"a metal tool with a special shape at the end for holding and turning things, including one that can be changed to fit objects of different sizes, also called a monkey wrench or an adjustable spanner","cn":"扳钳；扳手","g":"[countable]","lab":"especially North American English","pos":"noun"},{"en":"pain or unhappiness that you feel when you have to leave a person or place that you love","cn":"（离别的）痛苦，难受","g":"[singular]","ex":{"en":"Leaving home was a terrible wrench for me.","cn":"对我来说离开家是件十分痛苦的事。"},"pos":"noun"},{"en":"a sudden and violent twist or pull","cn":"猛扭；猛拉","g":"[countable, usually singular]","ex":{"en":"She stumbled and gave her ankle a painful wrench.","cn":"她绊了一跤，把脚踝崴得很痛。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"猛拉;猛拧;猛拽","en":"If you wrench something that is fixed in a particular position, you pull or twist it violently, in order to move or remove it.","ex":{"en":"He felt two men wrench the suitcase from his hand","cn":"他感觉有两个人在使劲拽他手里的手提箱。"}},{"pos":"VERB 动词","cn":"挣脱;挣开","en":"If you wrench yourself free from someone who is holding you, you get away from them by suddenly twisting the part of your body that is being held.","ex":{"en":"She wrenched herself from his grasp","cn":"她从他手里挣脱开来。"}},{"pos":"VERB 动词","cn":"扭伤(关节)","en":"If you wrench one of your joints, you twist it and injure it.","ex":{"en":"He had wrenched his ankle badly from the force of the fall.","cn":"他因摔倒而严重扭伤了脚踝。"}},{"pos":"N-SING 单数名词","cn":"(离别时的)痛苦，愁楚","en":"If you say that leaving someone or something is a wrench, you feel very sad about it.","ex":{"en":"I always knew it would be a wrench to leave Essex after all these years","cn":"我一直心里清楚过了这么多年后离开埃塞克斯会非常痛苦。"}},{"pos":"N-COUNT 可数名词","cn":"扳钳；活动扳手","en":"A wrench or a monkey wrench is an adjustable metal tool used for tightening or loosening metal nuts of different sizes."},{"pos":"PHRASE 短语","cn":"作梗;阻挠","en":"If someone throws a wrench or throws a monkey wrench into a process, they prevent something happening smoothly by deliberately causing a problem.","ex":{"en":"Their delegation threw a giant monkey wrench into the process this week by raising all sorts of petty objections.","cn":"他们的代表团本周提出了各种细枝末节的反对意见，极在地阻挠了进程。"}}]},"examples":[{"en":"He grabbed Ben, wrenching him away from his mother.","cn":"他抓住本，把他从他母亲那里一把抢走了。"},{"en":"The bag was wrenched from her grasp.","cn":"那只包从她紧握的手里被夺了出来。"}]},"wrestling":{"oxford":{"phon":"ˈreslɪŋ","pos":"noun","senses":[{"en":"a sport in which two people fight by holding each other and trying to throw or force their opponent to the ground","cn":"摔跤运动"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"摔跤(运动)","en":"Wrestling is a sport in which two people wrestle and try to throw each other to the ground.","ex":{"en":"...a championship wrestling match.","cn":"摔跤锦标赛比赛"}}]},"media":{"uk":"media/uk/wrestling__gb_1.mp3","us":"media/us/wrestling__us_1.mp3"}},"wrinkle":{"media":{"uk":"media/uk/wrinkle__gb_1.mp3","us":"media/us/wrinkle__us_1.mp3"},"oxford":{"phon":"ˈrɪŋkl","pos":"noun","senses":[{"en":"a line or small fold in your skin, especially on your face, that forms as you get older","cn":"（尤指脸上的）皱纹","lab":"informal","ex":{"en":"There were fine wrinkles around her eyes.","cn":"她眼角上出现了鱼尾纹。"}},{"en":"a small fold that you do not want in a piece of cloth or paper","cn":"（布或纸上的）褶皱，皱痕","g":"[usually plural]","lab":"figurative","ex":{"en":"I tried to iron out the wrinkles in my shirt.","cn":"我设法将衬衫上的褶皱熨平。"}},{"en":"to make the skin on your face form into lines or folds; to form lines or folds in this way","cn":"（使脸上）起皱纹；皱起","g":"[transitive, intransitive]","ex":{"en":"She wrinkled up her nose in distaste.","cn":"她厌恶地皱起鼻子。"},"pos":"verb"},{"en":"to form raised folds or lines in an untidy way; to make something do this","cn":"（使）起褶皱","g":"[intransitive, transitive]","ex":{"en":"Her stockings were wrinkling at the knees.","cn":"她长袜的膝盖处起了褶皱。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(脸上的)皱纹","en":"Wrinkles are lines which form on someone's face as they grow old.","ex":{"en":"His face was covered with wrinkles","cn":"他的脸上布满了皱纹。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)（皮肤）起皱纹","en":"When someone's skin wrinkles or when something wrinkles it, lines start to form in it because the skin is getting old or damaged.","ex":{"en":"The skin on her cheeks and around her eyes was beginning to wrinkle.","cn":"她两颊和双眼周围开始起了皱纹。"}},{"pos":"N-COUNT 可数名词","cn":"（布或纸的）褶皱，皱痕，褶子","en":"A wrinkle is a raised fold in a piece of cloth or paper that spoils its appearance.","ex":{"en":"He noticed a wrinkle in her stocking.","cn":"他注意到她长筒袜上有一道褶儿。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（衣服）起皱，起褶","en":"If cloth wrinkles, or if someone or something wrinkles it, it gets folds or lines in it.","ex":{"en":"Her stockings wrinkled at the ankles","cn":"她的长筒袜在脚踝处起了褶儿。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(鼻子、额头等)起皱","en":"When you wrinkle your nose or forehead, or when it wrinkles, you tighten the muscles in your face so that the skin folds.","ex":{"en":"Frannie wrinkled her nose at her daughter","cn":"弗兰妮朝她女儿皱了皱鼻子。"}}]},"examples":[{"en":"His face wrinkled in a grin.","cn":"他咧嘴一笑满脸都是皱纹。"},{"en":"Her stockings were wrinkling at the knees.","cn":"她长袜的膝盖处起了皱褶。"}]},"wrestler":{"oxford":{"phon":"ˈreslə(r)","pos":"noun","senses":[{"en":"a person who takes part in the sport of wrestling","cn":"摔跤运动员"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"摔跤运动员","en":"A wrestler is someone who wrestles as a sport, usually for money."}]},"media":{"uk":"media/uk/wrestler__gb_1.mp3","us":"media/us/wrestler__us_1.mp3"}},"wrist":{"media":{"uk":"media/uk/wrist__gb_1.mp3","us":"media/us/wrist__us_1.mp3"},"oxford":{"phon":"rɪst","pos":"noun","senses":[{"en":"the joint between the hand and the arm","cn":"手腕；腕关节","ex":{"en":"She's broken her wrist.","cn":"她的腕关节骨折了。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"腕;手腕","en":"Your wrist is the part of your body between your hand and your arm which bends when you move your hand."}]},"examples":[{"en":"He wore a copper bracelet on his wrist.","cn":"他腕上戴着只铜手镯。"},{"en":"She's broken her wrist.","cn":"她的腕关节骨折了。"}]},"wrote":{"collins":{"senses":[{"pos":"","cn":"","en":"Wrote is the past tense of write."}]},"media":{"uk":"media/uk/wrote__gb_1.mp3","us":"media/us/wrote__us_1.mp3"}},"writer":{"media":{"uk":"media/uk/writer__gb_1.mp3","us":"media/us/writer__us_1.mp3"},"oxford":{"phon":"ˈraɪtə(r)","pos":"noun","senses":[{"en":"a person whose job is writing books, stories, articles, etc.","cn":"作家；作者；著者","ex":{"en":"Who's your favourite writer?","cn":"你最喜欢的作家是谁？"}},{"en":"a person who has written a particular thing","cn":"写…的人；执笔者；撰写人","ex":{"en":"the writer of this letter","cn":"写这封信的人"}},{"en":"a person who forms letters in a particular way when they are writing","cn":"写字…的人","ex":{"en":"a messy writer","cn":"书写潦草的人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(专业)作家","en":"A writer is a person who writes books, stories, or articles as a job.","ex":{"en":"Turner is a writer and critic.","cn":"特纳是作家兼批评家。"}},{"pos":"N-COUNT 可数名词","cn":"（特定文章、报告、信件或故事的）作者，撰写者","en":"The writer of a particular article, report, letter, or story is the person who wrote it.","ex":{"en":"No-one is to see the document without the permission of the writer of the report","cn":"此报告未经作者允许，任何人不得翻阅。"}}]},"examples":[{"en":"a travel/cookery, etc. writer","cn":"游记作家、写菜谱的人等"},{"en":"the writer of this letter","cn":"写这封信的人"}]},"writes":{"oxford":{"phon":"raɪt","pos":"verb","senses":[{"en":"to make letters or numbers on a surface, especially using a pen or a pencil","cn":"书写；写字"},{"en":"to produce sth in written form so that people can read, perform or use it, etc.","cn":"写作；作曲；编写"}]}},"writers":{"oxford":{"phon":"ˈraɪtə(r)","pos":"noun","senses":[{"en":"a person whose job is writing books, stories, articles, etc.","cn":"作家；作者；著者"},{"en":"a person who has written a particular thing","cn":"写 … 的人；执笔者；撰写人"}]}},"wrongs":{"oxford":{"phon":"rɒŋ","pos":"adjective","senses":[{"en":"not right or correct","cn":"错误的；不对的；不正确的"},{"en":"not right about sth/sb","cn":"出错；搞错；有错误"}]}},"wreaked":{"oxford":{"phon":"riːk","pos":"verb","senses":[{"en":"( formal ) to do great damage or harm to sb/sth","cn":"造成（巨大的破坏或伤害）"}]}},"wriggling":{"oxford":{"phon":"ˈrɪɡl","pos":"verb","senses":[{"en":"to twist and turn your body or part of it with quick short movements","cn":"扭动身体；扭来扭去"},{"en":"to move somewhere by twisting and turning your body or part of it","cn":"蠕动；甩动而行；蜿蜒行进"}]}},"wrought":{"collins":{"senses":[{"pos":"VERB 动词","cn":"引起;造成","en":"If something has wrought a change, it has made it happen.","ex":{"en":"Events in Paris wrought a change in British opinion towards France and Germany.","cn":"巴黎发生的事件改变了英国对法国和德国的看法。"}},{"pos":"ADJ 形容词","cn":"以…原料制造的;以…方式制作的","en":"If something is wrought in a particular material or in a particular way, it has been created in that material or way.","ex":{"en":"...a walking stick with a gold head wrought in the form of a flower.","cn":"金质花形包头的拐杖"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the old past tense and past participle of work work","cn":"在旧时的过去式和过去分词"}]},"vocab":{"pos":"adj","senses":[{"en":"Wrought is an adjective that means \"molded,\" \"shaped,\" or \"manufactured.\" A wrought-iron fence has been shaped to fit a particular ornamental style."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41wrought.mp3","us":"media/ldoce/hwd/ame/4/ld44wrought.mp3"},"examples":[{"en":"This century wrought major changes in our society.","cn":"本世纪给我们的社会带来了重大变革。"},{"en":"The storm wrought havoc in the south.","cn":"这场暴风雨在南方造成了巨大的灾害。"}],"oxford":{"phon":"rɔːt","pos":"verb","senses":[{"en":"caused something to happen, especially a change","cn":"使发生了，造成了（尤指变化）","ex":{"en":"This century wrought major changes in our society.","cn":"本世纪给我们的社会带来了重大变革。"}}]}},"wrangler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"牧人;牧马人；牛仔","en":"A wrangler is a cowboy who works with cattle and horses."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a cowboy","cn":"牧人﹐牛仔"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41wrangler.mp3","us":"media/ldoce/hwd/ame/d/wrangler1.mp3"},"oxford":{"phon":"ˈræŋɡlə(r)","pos":"noun","senses":[{"en":"a cowboy or a cowgirl, especially one who takes care of horses","cn":"（尤指放马的）牛仔，女牛仔"}]}},"wrinkly":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"起皱的;有皱痕的","en":"A wrinkly surface has a lot of wrinkles on it.","ex":{"en":"...wrinkly cotton and wool stockings.","cn":"起了褶子的棉毛长筒袜"}},{"pos":"N-COUNT 可数名词","cn":"(年轻人对老人的戏称，尤用于拿老人开玩笑或取笑他们的举止时)老皱皮，老东西","en":"Young people sometimes refer to older people as wrinklies, especially when they are teasing them or making fun of the way they behave."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long thin mark on a piece of paper, the ground, or another surface","cn":""},{"en":"a thin line that has been cut into a surface","cn":""},{"en":"a deep line in the ground which has been made by the wheels of vehicles","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/wrinkle_v0205.mp3","us":"media/ldoce/hwd/ame/3/wrinkle1.mp3"},"examples":[{"en":"Her face was a mass of wrinkles.","cn":""},{"en":"She walked over to the bed and smoothed out the wrinkles.","cn":""}],"oxford":{"phon":"ˈrɪŋkli","pos":"adjective","senses":[{"en":"having wrinkles","cn":"皱的；有皱纹的"},{"en":"an offensive word for an old person","cn":"（对老年人的冒犯称呼）老皱皮","pos":"noun"}]}},"wreckage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(飞机、汽车等的)残骸；（建筑物等的）废墟","en":"When something such as a plane, car, or building has been destroyed, you can refer to what remains as wreckage or the wreckage .","ex":{"en":"Mark was dragged from the burning wreckage of his car.","cn":"马克被人从他着火的汽车残骸中拉了出来。"}},{"pos":"N-SING 单数名词","cn":"(计划等失败或遭到破坏后的)残余","en":"If something such as a plan has failed or been spoilt completely, you can refer to what remains as the wreckage of it.","ex":{"en":"New states were born out of the wreckage of old colonial empires.","cn":"新生国家从老殖民帝国的废墟中诞生。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the broken parts of a car, plane etc that has crashed","cn":""},{"en":"the parts of a building or town that remain after it has been destroyed","cn":""},{"en":"a ship that has been sunk, or a car that has been very badly damaged in a crash","cn":""}]},"collocations":{"phrases":["ADJ. mangled, tangled, twisted | blazing, burning, smoking | aircraft","QUANT. bit, piece Pieces of wreckage have been found up to three miles away.","VERB + WRECKAGE scatter, spread The crash left wreckage spread over a wide area. | be strewn with The runway is still strewn with wreckage. ","WRECKAGE + VERB be strewn Wreckage was strewn over a wide area.","PREP. amidst/among/amongst the ~ Bodies lay among the tangled wreckage. | in the ~ Her body was discovered in the wreckage. | ~ from A searc"]},"media":{"uk":"media/ldoce/hwd/bre/c/wreckage0205.mp3","us":"media/ldoce/hwd/ame/4/wreckage.mp3"},"examples":[{"en":"( figurative ) Could nothing be rescued from the wreckage of her dreams?","cn":"难道从她那破灭的梦想中就找不出一丝希望了吗？"},{"en":"Pieces of wreckage were found ten miles away from the scene of the explosion.","cn":"从离爆炸现场十英里外的地方发现了残骸碎片。"}],"oxford":{"phon":"ˈrekɪdʒ","pos":"noun","senses":[{"en":"the parts of a vehicle, building, etc. that remain after it has been badly damaged or destroyed","cn":"（车辆等的）残骸；（建筑物等的）废墟","lab":"figurative","ex":{"en":"A few survivors were pulled from the wreckage.","cn":"从废墟中扒出了几个幸存者。"}}]}},"wrecker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（事故发生后拖走坏损车辆的）救援车，救险车，清障车","en":"A wrecker is a motor vehicle which is used to pull broken or damaged vehicles to a place where they can be repaired or broken up, for example after an accident."},{"pos":"N-COUNT 可数名词","cn":"拆除废旧建筑者","en":"Wreckers are people whose job involves destroying old, unwanted, or damaged buildings."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who deliberately destroys something 〔","cn":"故意的〕破坏者"},{"en":"a vehicle that is used to take away damaged cars after an accident 〔","cn":"事故发生后拖走毁坏车辆的〕救援车﹐清障车"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41wrecker.mp3","us":"media/ldoce/hwd/ame/f/wrecker.mp3"},"examples":[{"en":"She accused him of being a marriage wrecker.","cn":"她指责他破坏婚姻。"}],"oxford":{"phon":"ˈrekə(r)","pos":"noun","senses":[{"en":"a person who destroys another person’s plans, relationship, etc.","cn":"（对他人计划、关系等的）破坏者","ex":{"en":"She saw him as the wrecker of all her dreams.","cn":"她把他视为她所有梦想的破坏者。"}},{"en":"a vehicle used for moving other vehicles that have been damaged in an accident","cn":"救援车","lab":"North American English","ex":{"en":"the wrecker’s yard","cn":"拆车场，汽车报废场"}}]}},"wreak":{"collins":{"senses":[{"pos":"VERB 动词","cn":"造成(混乱或破坏)","en":"Something or someone that wreaks havoc or destruction causes a great amount of disorder or damage.","ex":{"en":"Violent storms wreaked havoc on the French Riviera, leaving three people dead and dozens injured","cn":"猛烈的暴风雨给法国里维埃拉地区造成了极大的破坏，致使三人死亡，数十人受伤。"}},{"pos":"VERB 动词","cn":"实施(报复)","en":"If you wreak revenge or vengeance on someone, you do something that will harm them very much to punish them for the harm they have done to you.","ex":{"en":"He threatened to wreak vengeance on the men who toppled him a year ago.","cn":"他威胁要对一年前扳倒他的人进行报复。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have a bad effect on something, in a way that makes it weaker, less effective, or less successful","cn":""},{"en":"to permanently harm something such as the success, health, or image of a person, organization etc so that they are not as effective as before","cn":""},{"en":"to change or effect something in a harmful way","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To wreak is to cause something to happen, usually with a terrible consequence. You can make mischief, cause problems, or inflict pain, but to wreak damage suggests a deeper level of destruction."}]},"media":{"uk":"media/ldoce/hwd/bre/8/reek0205.mp3","us":"media/ldoce/hwd/ame/5/reek1.mp3"},"examples":[{"en":"Their policies would wreak havoc on the economy.","cn":"他们的政策将对经济造成巨大的破坏。"},{"en":"He swore to wreak vengeance on those who had betrayed him.","cn":"他发誓要对背叛他的人进行报复。"}],"oxford":{"phon":"riːk","pos":"verb","senses":[{"en":"to do great damage or harm to somebody/something","cn":"造成（巨大的破坏或伤害）","ex":{"en":"Their policies would wreak havoc on the economy.","cn":"他们的政策将对经济造成巨大的破坏。"}}]}},"wrinkled":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a line on a piece of clothing or material where it has been folded or crushed","cn":""},{"en":"a line in a piece of clothing that is caused when it has not been folded or hung properly, but instead has been left somewhere untidily","cn":""},{"en":"clothes that are wrinkled or creased have a lot of wrinkles or creases in them","cn":""}]},"collocations":{"phrases":["VERBS be | become","ADV. all, deeply, extremely, very His face was all wrinkled and old. | prematurely"]},"media":{"uk":"media/ldoce/hwd/bre/d/wrinkled0205.mp3","us":"media/ldoce/hwd/ame/6/laadwrinkled.mp3"},"examples":[{"en":"her wrinkled old face","cn":"她满是皱纹的苍老面容"}],"oxford":{"phon":"ˈrɪŋkld","pos":"adjective","senses":[{"en":"having wrinkles","cn":"有皱纹的","ex":{"en":"She kissed his wrinkled face.","cn":"她吻了他满是皱纹的脸。"}}]}},"write-off":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(发生事故后)报废的车辆","en":"Something such as a vehicle that is a write-off has been so badly damaged in an accident that it is not worth repairing.","ex":{"en":"The car was a write-off, but everyone escaped unharmed.","cn":"这辆车报废了，但人员全部安全逃离。"}},{"pos":"N-COUNT 可数名词","cn":"(债务或花费的)注销，勾销","en":"A write-off is the decision by a company or government to accept that they will never recover a debt or an amount of money that has been spent on something.","ex":{"en":"Mr James persuaded the banks to accept a large write-off of debt.","cn":"詹姆斯先生说服银行同意注销一大笔债务。"}},{"pos":"N-SING 单数名词","cn":"失败的计划;白费的时间","en":"If you describe a plan or period of time as a write-off, you mean that it has been a failure and you have achieved nothing.","ex":{"en":"Today was really a bit of a write-off for me","cn":"今天对我来说真的有点儿白白浪费了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the broken parts of a car, plane etc that has crashed","cn":""},{"en":"the parts of a building or town that remain after it has been destroyed","cn":""},{"en":"a ship that has been sunk, or a car that has been very badly damaged in a crash","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/write_off0205.mp3","us":"media/ldoce/hwd/ame/b/write-off.mp3"},"examples":[{"en":"With meetings and phone calls, yesterday was a complete write-off.","cn":"昨天都在开会和打电话，瞎忙了一天。"},{"en":"The car was a complete write-off.","cn":"那辆汽车彻底报废了。"}],"oxford":{"phon":"ˈraɪt ɒf","pos":"noun","senses":[{"en":"a vehicle that has been so badly damaged in an accident that cannot be repaired or would cost more to repair than to replace","cn":"报废车辆","lab":"British English","ex":{"en":"She survived the crash with minor injuries, but the car was a write-off.","cn":"她在碰撞中幸存，受了点儿轻伤，但汽车报废了。"}},{"en":"a period of time during which you do not achieve anything","cn":"无所作为的一段时间","g":"[singular]","lab":"informal","ex":{"en":"With meetings and phone calls, yesterday was a complete write-off.","cn":"昨天都在开会和打电话，瞎忙了一天。"}},{"en":"an act of cancelling a debt and accepting that it will never be paid","cn":"（债项的）注销，销记","lab":"business"}]}},"wry":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(表情)哭笑不得的","en":"If someone has a wry expression, it shows that they find a bad situation or a change in a situation slightly amusing.","ex":{"en":"Matthew allowed himself a wry smile","cn":"马修不由得苦笑了一下。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（话语或文章）挖苦的，讽刺的，揶揄的","en":"A wry remark or piece of writing refers to a bad situation or a change in a situation in an amusing way.","ex":{"en":"The play is a rueful, wry observation about the way we are all subject to the ravages of time","cn":"该剧凄然而讽刺地描述了我们大家是如何被岁月所摧残的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a wry expression or wry humour shows that you know a situation is bad, but you also think it is slightly amusing","cn":"啼笑皆非的﹐苦笑的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"A wry sense of humor is a sarcastic one. You were late for work, stepped into a mud puddle, and you forgot your lunch. If your co-worker asks how your morning is going, you can reply with a wry tone, \"Perfectly perfect.\""}]},"media":{"uk":"media/ldoce/hwd/bre/3/rye0205.mp3","us":"media/ldoce/hwd/ame/d/rye.mp3"},"examples":[{"en":"‘At least we got one vote,’ she said with a wry smile. “","cn":"我们起码还得了一票。”她苦笑着解嘲道。"},{"en":"He pulled a wry face when I asked him how it had gone.","cn":"我问他近况如何，他有些哭笑不得。"}],"oxford":{"phon":"raɪ","pos":"adjective","senses":[{"en":"showing that you think something is funny but also disappointing or annoying","cn":"啼笑皆非的","ex":{"en":"‘At least we got one vote,’ she said with a wry smile.","cn":"“我们起码还得了一票。”她苦笑着解嘲道。"}},{"en":"funny in a way that shows irony","cn":"挖苦的；讽刺的；揶揄的","ex":{"en":"It's a wry comedy about family life.","cn":"这是一部关于家庭生活的讽刺喜剧。"}}]}},"wrapper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指用于食品的)包装纸,包装塑料,包装用金属薄纸","en":"A wrapper is a piece of paper, plastic, or thin metal which covers and protects something that you buy, especially food.","ex":{"en":"I emptied the sweet wrappers from the ashtray.","cn":"我把烟灰缸里的糖纸倒掉。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is put on or over something else to protect it, for example a piece of metal, plastic, or glass","cn":""},{"en":"a layer of something, or a sheet of something, that covers something else","cn":""},{"en":"a cover for a container such as a pan or a box","cn":""}]},"collocations":{"phrases":["ADJ. chocolate, sweet | Cellophane(R), foil, paper, plastic | sealed | plain | empty","VERB + WRAPPER remove, take off, tear off | drop, throw away, throw down He dropped a sweet wrapper.","WRAPPER + VERB litter sth Sweet wrappers littered the floor.","PREP. in a/the ~ The book arrived in a plain brown wrapper. | on a/the ~ There was a list of ingredients on the wrapper. | out of a/the She "]},"media":{"uk":"media/ldoce/hwd/bre/4/wrapper0205.mp3","us":"media/ldoce/hwd/ame/a/wrapper.mp3"},"examples":[{"en":"( BrE ) sweet wrappers","cn":"糖果包装纸"},{"en":"( NAmE ) candy wrappers","cn":"糖果包装纸"}],"oxford":{"phon":"ˈræpə(r)","pos":"noun","senses":[{"en":"a piece of paper, plastic, etc. that is wrapped around something, especially food, when you buy it in order to protect it and keep it clean","cn":"（食品等的）包装材料，包装纸，包装塑料","lab":"British English","ex":{"en":"sweet wrappers","cn":"糖果包装纸"}},{"en":"a piece of cloth that is worn as an item of clothing around the lower body and legs","cn":"（腰际以下和腿部的）围裹式裙子","lab":"West African English"}]}},"wringer":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"受尽折磨;历尽艰辛","en":"If you say that someone has been put through the wringer or has gone through the wringer, you mean that they have suffered a very difficult or unpleasant experience."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a machine with two parts that roll over each other and press on wet clothes to remove water","cn":"衣物绞干机"},{"en":"to have a lot of problems and upsetting experiences","cn":"历经千辛万苦"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41wringer.mp3","us":"media/ldoce/hwd/ame/4/wringer.mp3"},"examples":[{"en":"She’s really been through the wringer since her husband died.","cn":"丈夫去世之后﹐她历尽艰辛。"}],"oxford":{"phon":"ˈrɪŋə(r)","pos":"noun","senses":[{"en":"a machine with two rollers used especially in the past for pressing the water out of clothes that had been washed","cn":"（尤指旧时的）衣物轧干机"}]}},"wren":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鹪鹩","en":"A wren is a very small brown bird. There are several kinds of wren."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very small brown bird","cn":"鹪鹩〔一种褐色小鸟〕"}]},"vocab":{"pos":"n","senses":[{"en":"That tiny brown bird you see flitting past your window may be a wren , especially if it's got a tiny, upright tail."}]},"media":{"uk":"media/ldoce/hwd/bre/4/wren0205.mp3","us":"media/ldoce/hwd/ame/0/wren1.mp3"},"oxford":{"phon":"ren","pos":"noun","senses":[{"en":"a very small brown bird","cn":"鹪鹩（形小，浅褐色）"}]}},"wraith":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鬼魂;幽灵","en":"A wraith is a ghost.","ex":{"en":"That child flits about like a wraith.","cn":"那个孩子像幽灵一样飞快地跑来跑去。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a ghost","cn":"鬼魂﹐幽灵；灵魂"}]},"vocab":{"pos":"n","senses":[{"en":"If you have a vision of your grandfather just before he passes away, you have seen a wraith or a ghostly image. Wraith can also mean something thin, wispy, or ghost-like."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41wraith.mp3","us":"media/ldoce/hwd/ame/2/wraith.mp3"},"examples":[{"en":"a wraith-like figure (= a very thin, pale person)","cn":"瘦削苍白、幽灵似的人"}],"oxford":{"phon":"reɪθ","pos":"noun","senses":[{"en":"the ghost of a person that is seen a short time before or after that person dies","cn":"（临终前后显现的）活人灵魂，鬼魂","ex":{"en":"a wraith-like figure (= a very thin, pale person)","cn":"瘦削苍白、幽灵似的人"}}]}},"wreath":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（用于祭奠的）花圈","en":"A wreath is an arrangement of flowers and leaves, usually in the shape of a circle, which you put on a grave or by a statue to show that you remember a person who has died or people who have died.","ex":{"en":"The coffin lying before the altar was bare, except for a single wreath of white roses","cn":"祭台前的棺木上除了仅有的一个白玫瑰花圈外，没有其他任何装饰。"}},{"pos":"N-COUNT 可数名词","cn":"（头上戴的）花环，花冠","en":"A wreath is a circle of leaves or flowers which someone wears around their head."},{"pos":"N-COUNT 可数名词","cn":"（某些人圣诞节时挂在家门上的）花环","en":"A wreath is a circle of leaves which some people hang on the front door of their house at Christmas."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a circle made from leaves or flowers that you put on the place where a person is buried 〔","cn":"放在墓前的〕花圈"},{"en":"a circle of leaves or flowers that people use to decorate their houses at Christmas 〔","cn":"圣诞节期间装饰屋子的〕花环"},{"en":"a circle made from leaves that a person wore on their head in the past as a sign of honour","cn":"花冠〔旧时荣誉的象征〕"}]},"vocab":{"pos":"n","senses":[{"en":"Got a wreath on your front door? That's one of those ring-shaped bands of flowers or foliage that people use for decoration. Wreaths go back to ancient times and maybe the circular shape symbolizes the eternal."}]},"collocations":{"phrases":["ADJ. Christmas, festive | holly, laurel, poppy","VERB + WREATH lay The Queen laid a poppy wreath at the war memorial. | send He didn't come to the funeral but he sent a wreath. | be crowned","PREP. ~ of She wore a wreath of roses round her head."]},"media":{"img":["media/ldoce/img/wreath.jpg"],"uk":"media/ldoce/hwd/bre/1/wreath0205.mp3","us":"media/ldoce/hwd/ame/3/wreath.mp3"},"examples":[{"en":"The Queen laid a wreath at the war memorial.","cn":"女王向阵亡将士纪念碑献了花圈。"},{"en":"a holly wreath","cn":"圣诞冬青花环"}],"oxford":{"phon":"riːθ","pos":"noun","senses":[{"en":"an arrangement of flowers and leaves, especially in the shape of a circle, placed on graves, etc. as a sign of respect for somebody who has died","cn":"花圈（用于祭奠）","ex":{"en":"The Queen laid a wreath at the war memorial.","cn":"女王向阵亡将士纪念碑献了花圈。"}},{"en":"an arrangement of flowers and/or leaves in the shape of a circle, traditionally hung on doors as a decoration at Christmas","cn":"花环（传统上圣诞节时挂在门上）","ex":{"en":"a holly wreath","cn":"圣诞冬青花环"}},{"en":"a circle of flowers or leaves worn on the head, and used in the past as a sign of honour","cn":"花冠（旧时用作荣誉的象征）","ex":{"en":"a laurel wreath","cn":"桂冠"}},{"en":"a circle of smoke, cloud, etc.","cn":"（烟、云等的）圈，缭绕","lab":"literary","ex":{"en":"wreaths of mist","cn":"薄雾缭绕。"}}]}},"wring":{"collins":{"senses":[{"pos":"VERB 动词","cn":"强行取得;逼取","en":"If you wring something out of someone, you manage to make them give it to you even though they do not want to.","ex":{"en":"Buyers use different ruses to wring free credit out of their suppliers","cn":"买主们千方百计想从供货商那儿无息赊购。"}},{"pos":"PHRASE 短语","cn":"(通常因忧愁、焦虑而)绞扭双手（干叹息)","en":"If someone wrings their hands, they hold them together and twist and turn them, usually because they are very worried or upset about something. You can also say that someone is wringing their hands when they are expressing sorrow that a situation is so bad but are saying that they are unable to change it.","ex":{"en":"The Government has got to get a grip. Wringing its hands and saying it is a world problem just isn't good enough.","cn":"政府必须采取切实行动，一味搓着手感叹说这是个全球性问题是远远不够的。"}},{"pos":"PHRASE 短语","cn":"扭断…的脖子(表示非常生某人的气)","en":"If you say that you will wring someone's neck or that you would like to wring their neck, you mean that you are very angry or irritated with them.","ex":{"en":"That crazy Debbie! He could wring her neck for this!","cn":"黛比那个疯子！他会为这把她的脖子拧断的！"}},{"pos":"","cn":"","en":"相关词组：wring out"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to press and twist wet cloth or wet clothes in order to remove water from them","cn":""},{"en":"to succeed in getting something from someone, but only after a lot of effort 〔","cn":"从某人处〕费力弄到〔某物〕"},{"en":"to tightly twist a wet cloth or wet clothes in order to remove water","cn":"把〔湿布或湿衣服〕拧干﹔绞出〔水〕"}]},"vocab":{"pos":"n v","senses":[{"en":"To wring something is to twist or squeeze it, usually out of its original shape. If you annoy someone enough, they might threaten to wring your neck."}]},"media":{"img":["media/ldoce/img/ldoce_355.png","media/thumb/wring.jpg"],"uk":"media/ldoce/hwd/bre/3/wring0205.mp3","us":"media/ldoce/hwd/ame/5/ring1.mp3"},"examples":[{"en":"They are always trying to wring additional funds from the government.","cn":"他们总想从政府手中搞到更多的资金。"},{"en":"I managed to wring the information out of him.","cn":"我想法从他那里弄到了这些信息。"}],"oxford":{"phon":"rɪŋ","pos":"verb","senses":[{"en":"to twist and squeeze wet clothes, etc. in order to get the water out of them","cn":"拧，绞，拧出，绞出（湿衣服等中的水）"},{"en":"if you wring a bird’s neck, you twist it in order to kill the bird","cn":"拧，扭（鸟的脖子，以将其杀死）"}]}},"wrongful":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"违法的;不道德的;不公正的","en":"A wrongful act is one that is illegal, immoral, or unjust.","ex":{"en":"He is on hunger strike in protest at what he claims is his wrongful conviction for murder","cn":"他称他的谋杀罪为错判，因而进行绝食抗议。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a wrongful arrest etc is unfair or illegal because the person affected by it has done nothing wrong","cn":"不公正[非法]的逮捕/判决/入狱/解雇等"}]},"media":{"uk":"media/ldoce/hwd/bre/4/wrongful0205.mp3","us":"media/ldoce/hwd/ame/5/wrongful.mp3"},"examples":[{"en":"She decided to sue her employer for wrongful dismissal.","cn":"她决定起诉雇主非法解雇她。"},{"en":"to be wrongfully convicted/dismissed","cn":"遭非法定罪/解雇"}],"oxford":{"phon":"ˈrɒŋfl","pos":"adjective","senses":[{"en":"not fair, morally right or legal","cn":"不公正的；不道德的；不合法的","ex":{"en":"She decided to sue her employer for wrongful dismissal.","cn":"她决定起诉雇主非法解雇她。"}}]}},"write-in":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(美国选举中)投给非推荐候选人的票","en":"In the US, a write-in is a vote that you make by writing the candidate's name on the ballot paper.","ex":{"en":"When Republican write-ins were included, Johnson's margin of victory was only 330 votes","cn":"将共和党非推荐候选人所获选票计入在内的话，约翰逊只多赢了330票。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a vote you give to someone by writing their name on your ballot paper","cn":"投给非候选人的票"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41write-in.mp3","us":"media/ldoce/hwd/ame/6/write-in.mp3"},"oxford":{"phon":"ˈraɪt ɪn","pos":"noun","senses":[{"en":"a vote for somebody who is not an official candidate in an election, in which you write their name on your ballot paper","cn":"投给非候选人的票"}]}},"wrongdoing":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"违法行为;犯罪行为;不道德行为","en":"Wrongdoing is behaviour that is illegal or immoral.","ex":{"en":"The city attorney's office hasn't found any evidence of criminal wrongdoing.","cn":"市检察官办公室尚未发现任何刑事犯罪的证据。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"bad or immoral behaviour, especially relating to sex","cn":""},{"en":"bad or immoral behaviour, especially involving crimes or not being fair or just","cn":""},{"en":"bad behaviour by someone in a position of authority or trust, who is expected to behave according to the rules of their profession","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/wrongdoing0205.mp3","us":"media/ldoce/hwd/ame/b/amelasdewrongdoing.mp3"},"oxford":{"phon":"ˈrɒŋduːɪŋ","pos":"noun","senses":[{"en":"illegal or dishonest behaviour","cn":"不法行为；坏事；作恶；欺骗行径","ex":{"en":"The company denies any wrongdoing.","cn":"该公司否认有任何不法行为。"}}]}},"writ":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"令状;法院命令;传票","en":"A writ is a legal document that orders a person to do a particular thing.","ex":{"en":"He issued a writ against one of his accusers.","cn":"他向其中一个指控他的人发了传票。"}},{"pos":"PHRASE 短语","cn":"明显的;显而易见的","en":"If you say that something is writ large, you mean that it is very obvious.","ex":{"en":"They now have to cope with the legacy of their past incompetence writ large on their balance sheets.","cn":"他们现在不得不处理由于过去工作不力所遗留下的问题,这在资产负债表上一看便知。"}},{"pos":"PHRASE 短语","cn":"扩大了的;夸大了的","en":"If you say that one thing is another thing writ large, you mean that the first thing is a larger or more exaggerated version of the second thing.","ex":{"en":"Her life was her personality writ large.","cn":"她的生活是她性格放大了的写照。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a document from a court that orders someone to do or not to do something 〔","cn":"法院的〕令状﹐书面命令"},{"en":"very easy to notice","cn":"显著的﹐显眼的﹔引人注目的"},{"en":"in a very clear strong form","cn":"明摆着的"}]},"vocab":{"pos":"n","senses":[{"en":"If you are ever served with a writ , then you better do what it says. A writ is a written document issuing a legal order."}]},"collocations":{"phrases":["ADJ. High Court, Supreme Court, etc. | legal | libel, personal injury, etc.","VERB + WRIT apply for, obtain Creditors could obtain a writ for the arrest of their debtors. | file, issue, serve A writ was filed in the Hi","PREP. in a/the ~ 22 defendants are named in the writ. | ~ against The businessmen have issued a writ against the authority for damages. | ~ "]},"media":{"uk":"media/ldoce/hwd/bre/1/writ_n0205.mp3","us":"media/ldoce/hwd/ame/d/writ1.mp3"},"examples":[{"en":"The company has been served with a writ for breach of contract.","cn":"这家公司因违约已接到法院令状。"},{"en":"Mistrust was writ large on her face.","cn":"她脸上明显流露出不信任的神情。"}],"oxford":{"phon":"rɪt","pos":"noun","senses":[{"en":"a legal document from a court telling somebody to do or not to do something","cn":"（法庭的）令状，书面命令","ex":{"en":"The company has been served with a writ for breach of contract.","cn":"这家公司因违约已接到法院令状。"}}]}},"wrestle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"试图解决;绞尽脑汁处理","en":"When you wrestle with a difficult problem, you try to deal with it.","ex":{"en":"Delegates wrestled with the problems of violence and sanctions","cn":"代表们试图解决暴力与惩处的问题。"}},{"pos":"VERB 动词","cn":"摔跤;扭斗","en":"If you wrestle with someone, you fight them by forcing them into painful positions or throwing them to the ground, rather than by hitting them. Some people wrestle as a sport.","ex":{"en":"They taught me to wrestle","cn":"他们教我摔跤。"}},{"pos":"VERB 动词","cn":"使劲搬动;用力移动","en":"If you wrestle a person or thing somewhere, you move them there using a lot of force, for example by twisting a part of someone's body into a painful position.","ex":{"en":"We had to physically wrestle the child from the man's arms","cn":"我们只得用力把孩子从那个男子手中夺过来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if people fight , or if one person fights another, they hit or kick each other in order to hurt each other","cn":""},{"en":"to fight with another person","cn":""},{"en":"to fight someone who is attacking you or holding you, especially so that you can escape from them","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you decide to wrestle on a team in high school, you'll be grabbing your opponent and trying to fling him to the ground while he tries to do the same to you. You might want to consider the ping pong team instead."}]},"media":{"uk":"media/ldoce/hwd/bre/3/wrestle0205.mp3","us":"media/ldoce/hwd/ame/0/wrestle.mp3"},"examples":[{"en":"She had spent the whole weekend wrestling with the problem.","cn":"她整个周末都在绞尽脑汁处理这个问题。"},{"en":"He wrestled with the controls as the plane plunged.","cn":"飞机向下冲时，他竭力控制住操纵装置。"}],"oxford":{"phon":"ˈresl","pos":"verb","senses":[{"en":"to fight somebody by holding them and trying to throw or force them to the ground, sometimes as a sport","cn":"摔跤","g":"[intransitive, transitive]","ex":{"en":"As a boy he had boxed and wrestled.","cn":"他小时候练过拳击和摔跤。"}},{"en":"to struggle physically to move or manage something","cn":"努力移动（或操纵）；用力对付","g":"[intransitive, transitive]","ex":{"en":"He wrestled with the controls as the plane plunged.","cn":"飞机向下冲时，他竭力控制住操纵装置。"}},{"en":"to struggle to deal with something that is difficult","cn":"奋力对付；努力处理；全力解决","g":"[intransitive]","ex":{"en":"She had spent the whole weekend wrestling with the problem.","cn":"她整个周末都在绞尽脑汁处理这个问题。"}}]}},"wriggle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"蠕动，扭动(身体的一部分)","en":"If you wriggle or wriggle part of your body, you twist and turn with quick movements, for example because you are uncomfortable.","ex":{"en":"The babies are wriggling on their tummies","cn":"婴儿们趴着，扭来扭去。"}},{"pos":"VERB 动词","cn":"扭动着行进;蠕动着行进","en":"If you wriggle somewhere, for example through a small gap, you move there by twisting and turning your body.","ex":{"en":"He clutched the child tightly as she again tried to wriggle free","cn":"孩子一扭一扭地又想挣脱，他紧紧地抓住了她。"}},{"pos":"","cn":"","en":"相关词组：wriggle out of"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go to a different place, or change the position of your body","cn":""},{"en":"to move slowly from one side to the other","cn":""},{"en":"to move repeatedly from one side to another, with small gentle movements","cn":""}]},"collocations":{"phrases":["ADV. uncomfortably The children wriggled uncomfortably in their seats. | free The dog wriggled free of his grasp and ran off. | about, away","PHRASES wriggle your way She wriggled her way under the heavy eiderdown."]},"media":{"uk":"media/ldoce/hwd/bre/9/wriggle_v0205.mp3","us":"media/ldoce/hwd/ame/3/wriggle1.mp3"},"examples":[{"en":"He tried desperately to wriggle out of giving a clear answer.","cn":"他竭力支支吾吾不给予明确的回答。"},{"en":"The fish wriggled out of my fingers.","cn":"那条鱼从我指缝中一甩身溜走了。"}],"oxford":{"phon":"ˈrɪɡl","pos":"verb","senses":[{"en":"to twist and turn your body or part of it with quick, short movements","cn":"扭动身体；扭来扭去","g":"[intransitive, transitive]","ex":{"en":"The baby was wriggling around on my lap.","cn":"婴儿在我大腿上扭来扭去。"}},{"en":"to move somewhere by twisting and turning your body or part of it","cn":"蠕动；甩动而行；蜿蜒行进","g":"[intransitive, transitive]","ex":{"en":"The fish wriggled out of my fingers.","cn":"那条鱼从我指缝中一甩身溜走了。"}},{"en":"an act of wriggling","cn":"扭动；蠕动；蜿蜒行进","pos":"noun"}]}},"wreathe":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(烟、雾等)笼罩，缭绕","en":"If something is wreathed in smoke or mist, it is surrounded by it.","ex":{"en":"The ship was wreathed in smoke","cn":"船笼罩在烟雾中。"}},{"pos":"VERB 动词","cn":"（花草）环绕;用（花环等）装饰","en":"If something is wreathed with flowers or leaves, it has a circle or chain of flowers or leaves put round it.","ex":{"en":"Its huge columns were wreathed with laurel and magnolia.","cn":"其巨大的立柱为月桂和木兰花所环绕。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be covered in something","cn":"被某物环绕[遮盖]"},{"en":"to be smiling and look very happy","cn":"笑容满面"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41wreathe.mp3","us":"media/ldoce/hwd/ame/0/wreathe.mp3"},"examples":[{"en":"The mountain tops were wreathed in mist.","cn":"山顶笼罩在薄雾之中。"},{"en":"( figurative ) Her face was wreathed in smiles (= she was smiling a lot).","cn":"她脸上乐开了花。"}],"oxford":{"phon":"riːð","pos":"verb","senses":[{"en":"to surround or cover something","cn":"环绕；覆盖；笼罩","g":"[transitive, usually passive]","lab":"figurative","ex":{"en":"The mountain tops were wreathed in mist.","cn":"山顶笼罩在薄雾之中。"}},{"en":"to move slowly and lightly, especially in circles","cn":"缓缓移动；盘绕；缠绕；萦绕","g":"[intransitive]","lab":"literary","ex":{"en":"smoke wreathing into the sky","cn":"袅袅升空的烟"}}]}},"wrongdoer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"作恶者;违法犯罪者","en":"A wrongdoer is a person who does things that are immoral or illegal."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"bad or immoral behaviour, especially relating to sex","cn":""},{"en":"bad or immoral behaviour, especially involving crimes or not being fair or just","cn":""},{"en":"bad behaviour by someone in a position of authority or trust, who is expected to behave according to the rules of their profession","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/wrongdoing0205.mp3","us":"media/ldoce/hwd/ame/b/amelasdewrongdoing.mp3"},"oxford":{"phon":"ˈrɒŋduːə(r)","pos":"noun","senses":[{"en":"a person who does something dishonest or illegal","cn":"做坏事的人；违法犯罪者；作恶者","ex":{"en":"Most people believed that wrongdoers should be made to suffer.","cn":"大多数人认为，应该让作恶者受苦。"}}]}},"wrangle":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"(长时间)吵架，争吵，争论","en":"If you say that someone is wrangling with someone over a question or issue, you mean that they have been arguing angrily for quite a long time about it.","ex":{"en":"The two sides have spent most of their time wrangling over procedural problems","cn":"双方大部分时间都在围绕程序问题争论不休。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long and complicated argument 〔","cn":"持久而复杂的〕争辩"},{"en":"to argue with someone angrily for a long time 〔","cn":"长时间地〕吵架﹐争论"}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"A long, hard, intense argument, especially over an issue with lots of details, is a wrangle. Politicians and lawyers frequently engage in wrangles. Usually it doesn't come to blows."}]},"collocations":{"phrases":["ADJ. bitter | complex | legal","VERB + WRANGLE be involved in, get into, have","WRANGLE + VERB ensue | continue, go on The legal wrangle continues.","PREP. in a/the ~ The two countries fell out in a bitter wrangle over imports. | ~ between The wrangle between the school and the local counc"]},"media":{"uk":"media/ldoce/hwd/bre/c/wrangle_n0205.mp3","us":"media/ldoce/hwd/ame/0/wrangle1.mp3"},"examples":[{"en":"a legal wrangle between the company and their suppliers","cn":"这家公司与各供货商之间长期的法律纠纷"},{"en":"They're still wrangling over the financial details.","cn":"他们仍在为财务细节争吵。"}],"oxford":{"phon":"ˈræŋɡl","pos":"noun","senses":[{"en":"an argument that is complicated and continues over a long period of time","cn":"（长时间的）争论，争吵","ex":{"en":"a legal wrangle between the company and their suppliers","cn":"这家公司与各供货商之间长期的法律纠纷"}},{"en":"to argue angrily and usually for a long time about something","cn":"（通常为长时间地）争吵，争辩","ex":{"en":"They're still wrangling over the financial details.","cn":"他们仍在为财务细节争吵。"},"pos":"verb"}]}},"wrath":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同 anger","en":"Wrath means the same as anger .","ex":{"en":"He incurred the wrath of the authorities in speaking out against government injustices.","cn":"他直言批评政府的不公正做法，招致当局震怒。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very strong feeling of anger","cn":""},{"en":"a very strong feeling of anger that is difficult to control or is expressed very suddenly or violently","cn":""},{"en":"extreme anger and shock because you think something is unfair or wrong","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Wrath is great anger that expresses itself in a desire to punish someone: Noah saw the flood as a sign of the wrath of God."}]},"collocations":{"phrases":["ADJ. full, great | divine They saw the floods as a sign of divine wrath.","VERB + WRATH arouse, bring (down), feel, incur, provoke This remark brought the judge's full wrath down on Sergeant Golding. This is the sec","PREP. ~ at his wrath at the insult | ~ of the wrath of God | ~ over the government's wrath over the incident"]},"media":{"uk":"media/ldoce/hwd/bre/a/wrath0205.mp3","us":"media/ldoce/hwd/ame/0/wrath.mp3"},"examples":[{"en":"the wrath of God","cn":"上帝的愤怒"},{"en":"He was scared of incurring his father’s wrath .","cn":"他害怕惹他父亲大发脾气。"}],"oxford":{"phon":"rɒθ","pos":"noun","senses":[{"en":"extreme anger","cn":"盛怒；震怒；怒火","ex":{"en":"the wrath of God","cn":"上帝的愤怒"}}]}},"writhe":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(通常指由于剧痛或不适而)扭动，翻滚","en":"If you writhe, your body twists and turns violently backwards and forwards, usually because you are in great pain or discomfort.","ex":{"en":"He was writhing in agony","cn":"他痛苦地翻滚着。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to keep moving or playing with your fingers, hands, feet etc, because you are bored or nervous","cn":""},{"en":"if you can't keep still , you keep moving your body because you are excited or nervous and you cannot relax","cn":""},{"en":"to make very small movements from side to side with your body, especially because you are in pain or uncomfortable","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To writhe is to squirm and twist. Often you'll see the phrase \"to writhe in agony.\" Writhe when you've just ingested some stomach-wrenching poison, or perhaps in response to red ant stings."}]},"media":{"uk":"media/ldoce/hwd/bre/5/writhe0205.mp3","us":"media/ldoce/hwd/ame/f/writhe.mp3"},"examples":[{"en":"The snake writhed and hissed.","cn":"那蛇蠕动着，发出嘶嘶的声音。"},{"en":"She was writhing around on the floor in agony.","cn":"她痛得在地板上直打滚。"}],"oxford":{"phon":"raɪð","pos":"verb","senses":[{"en":"to twist or move your body without stopping, often because you are in great pain","cn":"（常指因剧痛不停地）扭动，翻滚","lab":"figurative","ex":{"en":"She was writhing around on the floor in agony.","cn":"她痛得在地板上直打滚。"}}]}},"wretch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"不幸的人;可怜的人","en":"You can refer to someone as a wretch when you feel sorry for them because they are unhappy or unfortunate.","ex":{"en":"Before the poor wretch had time to speak, he was shot.","cn":"这个可怜的人还没来得及开口就中了枪。"}},{"pos":"N-COUNT 可数名词","cn":"坏蛋;恶棍;卑鄙小人","en":"You can refer to someone as a wretch when you think that they are wicked or if they have done something you are angry about.","ex":{"en":"Oh, what have you done, you wretch!","cn":"噢，你都干了些什么，你这个混蛋！"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone that you feel sorry for","cn":"可怜的人"},{"en":"someone you are annoyed with","cn":"淘气鬼﹔家伙"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A wretch is someone who is so miserable and unlucky that you almost have to feel sorry for the person. You might pity the poor wretch who was fired at work over something that wasn’t even his fault."}]},"media":{"uk":"media/ldoce/hwd/bre/a/retch0205.mp3","us":"media/ldoce/hwd/ame/a/retch.mp3"},"examples":[{"en":"a poor wretch","cn":"可怜的人"},{"en":"He was a lonely, miserable wretch.","cn":"他是一个孤独的可怜虫。"}],"oxford":{"phon":"retʃ","pos":"noun","senses":[{"en":"a person that you feel sympathy for or are sad about","cn":"不幸的人；可怜的人","lab":"literary","ex":{"en":"a poor wretch","cn":"可怜的人"}},{"en":"an evil, unpleasant or annoying person","cn":"恶棍；坏蛋；无赖；无耻之徒","lab":"often humorous","ex":{"en":"The little wretches have splashed water all over the bathroom.","cn":"这群小家伙把浴室里的水溅得到处都是。"}}]}},"wrest":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(尤指艰难或非法地)攫取，抢夺","en":"If you wrest something from someone else, you take it from them, especially when this is difficult or illegal.","ex":{"en":"For the past year he has been trying to wrest control from the central government","cn":"一年来，他一直试图从中央政府手中将控制权夺过来。"}},{"pos":"VERB 动词","cn":"抢，夺(物品)","en":"If you wrest something from someone who is holding it, you take it from them by pulling or twisting it violently.","ex":{"en":"He wrested the suitcase from the chauffeur","cn":"他从司机手里抢过手提箱。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take power or influence away from someone, especially when this is difficult","cn":"攫取〔权力或影响〕"},{"en":"to pull something away from someone violently","cn":"猛拉﹐抢夺"}]},"vocab":{"pos":"v","senses":[{"en":"To wrest is to forcefully grab or take something away. You can wrest away many things, such as remote controls and championships."}]},"media":{"uk":"media/ldoce/hwd/bre/e/wrest0205.mp3","us":"media/ldoce/hwd/ame/1/rest1.mp3"},"examples":[{"en":"They attempted to wrest control of the town from government forces.","cn":"他们企图从政府军手中夺取对这个城镇的控制权。"},{"en":"He wrested the gun from my grasp.","cn":"他把枪从我手里抢走了。"}]},"wristwatch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手表；腕表","en":"A wristwatch is a watch with a strap which you wear round your wrist."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a watch that you wear on your wrist","cn":"手表﹐腕表"}]},"media":{"uk":"media/ldoce/hwd/bre/b/wristwatch0205.mp3","us":"media/ldoce/hwd/ame/6/wristwatch.mp3"},"oxford":{"phon":"ˈrɪstwɒtʃ","pos":"noun","senses":[{"en":"a watch that you wear on your wrist","cn":"手表","ex":{"en":"Her wristwatch beeped.","cn":"她的腕表发出哔哔声。"}}]}}});
